-- Full corrected import: 05 Monthly HSSE May.docx and 06 Monthly HSSE June.docx.
-- Run after migration 022. Safe to re-run: target months are updated/replaced.

begin;

insert into public.reporting_periods(period_date) values ('2025-06-01') on conflict (period_date) do nothing;
insert into public.report_section_status(reporting_period_id, report_section_id)
select p.id, s.id from public.reporting_periods p cross join public.report_sections s
where p.period_date='2025-06-01' and s.is_active on conflict do nothing;
insert into public.monthly_submissions(reporting_period_id, department_id)
select p.id, d.id from public.reporting_periods p cross join public.departments d
where p.period_date='2025-06-01' and d.is_active on conflict do nothing;

update public.hse_incident_types set inception_baseline=case code
when 'BANKERS_LTI' then 20 when 'CONTRACTOR_LTI' then 63 when 'RESTRICTED_WORK_CASE' then 29 when 'PERSONNEL_INJURY_FA' then 158 when 'PERSONNEL_INJURY_MT' then 65 when 'PROPERTY_DAMAGE' then 230 when 'NEAR_MISS' then 331 when 'ENVIRONMENTAL' then 737 when 'SECURITY' then 4372 when 'MOTOR_VEHICLE_ACCIDENTS' then 503 when 'FATALITY' then 1 when 'FIRES' then 60 when 'NON_TABULATED' then 30 else inception_baseline end;

insert into public.hse_incident_ytd_baselines(reporting_year,incident_type_id,incident_count,source_reference)
select 2025,id,case code when 'CONTRACTOR_LTI' then 1 when 'PROPERTY_DAMAGE' then 1 when 'ENVIRONMENTAL' then 8 when 'SECURITY' then 2 when 'MOTOR_VEHICLE_ACCIDENTS' then 3 else 0 end,'05 Monthly HSSE May.docx Table 1.1-1' from public.hse_incident_types
on conflict (reporting_year,incident_type_id) do update set incident_count=excluded.incident_count,source_reference=excluded.source_reference,updated_at=now();
insert into public.hse_exposure_ytd_baselines(reporting_year,bankers_hours,contractor_hours,source_reference) values(2025,222380,419261,'05 Monthly HSSE May.docx Table 1.1-4') on conflict(reporting_year) do update set bankers_hours=excluded.bankers_hours,contractor_hours=excluded.contractor_hours,source_reference=excluded.source_reference,updated_at=now();
insert into public.hse_exposure_inception_baselines(id,bankers_hours,contractor_hours,source_reference) values(true,17641013,46796515,'05 Monthly HSSE May.docx Table 1.1-4') on conflict(id) do update set bankers_hours=excluded.bankers_hours,contractor_hours=excluded.contractor_hours,source_reference=excluded.source_reference,updated_at=now();
insert into public.hse_recordable_baselines(reporting_year,ytd_total_recordable,inception_total_recordable,source_reference) values(2025,1,178,'05 Monthly HSSE May.docx Table 1.1-1') on conflict(reporting_year) do update set ytd_total_recordable=excluded.ytd_total_recordable,inception_total_recordable=excluded.inception_total_recordable,source_reference=excluded.source_reference,updated_at=now();

