delete from public.hse_narratives where reporting_period_id in(select id from public.reporting_periods where period_date in('2025-05-01','2025-06-01'));
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'OPERATIONS_SUPPORT',jsonb_build_object('html',$mop$<ul><li>Attend contractors Weekly safety meetings.</li><li>Held monthly safety meetings with all department of BPAL.</li><li>Ongoing support including Acid jobs, Work over processes, hot works permits, confined space entry and tank cleaning, air monitoring for confined space entry, BPAL site works, lease and contractor inspections, non-conformities noted, reported and rectified.</li><li>Conducted work site, truck, rig and lease inspections throughout the Patos-Marinza field.</li><li>Gas readings and H2S support: 323 gas readings and 26 Safety Supports during May.</li><li>Fire extinguishers inspection 9; fire suppression system inspections 21; fire truck support 5.</li></ul>$mop$) from public.reporting_periods where period_date='2025-05-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'INCIDENT_INVESTIGATIONS',jsonb_build_object('html','<p>Completed incident investigations and reports as required. There were 03 Incidents reported in May.</p>') from public.reporting_periods where period_date='2025-05-01';
