insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'HS_TRAINING',jsonb_build_object('html',$mtrain$<ul><li>H2S awareness training - 40 hours.</li><li>WAH training - 24 hours.</li><li>Firefighting training - 6 hours.</li><li>Fire suppression systems inspection - 21.</li><li>Fire extinguishers inspected - 9.</li><li>eGSO Inductions - 10.</li><li>Safety Orientations - 100.</li><li>Defensive driving training - 2.</li><li>Work site inspections - 77.</li><li>Facility/Safety Inspections - 7.</li><li>Truck inspections - 16.</li><li>Rig inspections - 6.</li><li>Hot Work permits - 81.</li></ul>$mtrain$) from public.reporting_periods where period_date='2025-05-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'HEALTH',jsonb_build_object('html','<p>Continue health monitoring by BPAL/MRDC medical staff in Patos Marinza.</p><p>There were 70 visits; 59 first visits and 11 follow up, at the CTF medical facility by BPAL and Contractor employees in the May reporting period.</p>') from public.reporting_periods where period_date='2025-05-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'OPERATIONS_SUPPORT',jsonb_build_object('html',$jop$<ul><li>Attend contractors Weekly safety meetings.</li><li>Held monthly safety meetings with all department of BPAL.</li><li>Ongoing support including Acid jobs, Work over processes, hot works permits, confined space entry and tank cleaning, air monitoring for confined space entry, BPAL site works, lease and contractor inspections, non-conformities noted, reported and rectified.</li><li>Gas readings and H2S support: 1093 gas readings and 2 Safety Supports during June.</li><li>Fire extinguishers inspection 25; fire suppression system inspections 26; fire truck support 16.</li></ul>$jop$) from public.reporting_periods where period_date='2025-06-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'INCIDENT_INVESTIGATIONS',jsonb_build_object('html','<p>Completed incident investigations and reports as required. There were 04 Incidents reported in June.</p>') from public.reporting_periods where period_date='2025-06-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'INCIDENT_BREAKDOWN',jsonb_build_object('html','<p>See the imported H and S incident detail records for June 2025.</p>') from public.reporting_periods where period_date='2025-06-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'HS_TRAINING',jsonb_build_object('html',$jtrain$<ul><li>H2S Awareness training - 84 Hours.</li><li>WAH training - 24 hours.</li><li>Firefighting training - 22 hours.</li><li>Fire suppression systems inspection - 21.</li><li>Fire extinguishers inspected - 9.</li><li>eGSO Inductions - 08.</li><li>Safety Orientations - 34.</li><li>Hot Work permits - 68.</li></ul>$jtrain$) from public.reporting_periods where period_date='2025-06-01';
insert into public.hse_narratives(reporting_period_id,section_code,content) select id,'HEALTH',jsonb_build_object('html','<p>Continue health monitoring by BPAL/MRDC medical staff in Patos Marinza.</p><p>There were 100 visits; 75 first visits and 25 follow up, at the CTF medical facility by BPAL and Contractor employees in the June reporting period.</p>') from public.reporting_periods where period_date='2025-06-01';

