select id,3,jsonb_build_object('html',$menv$<ul><li>Ongoing site audits and inspections, including water, noise and air monitoring and sampling, environmental compliance audits, lease and well site inspections.</li><li>Monitoring of fluid levels in ecopits and wet mud facility.</li><li>The Ecology pits receiving waste this month were Ecopit 3 and 8.</li><li>The value for all other pits was zero.</li><li>Lease remediation and material reuse: 11332 m3 of clean soil stored near Pad D was reused during photovoltaics lease construction.</li></ul>$menv$),jsonb_build_object('html','<p>See imported environmental incident detail records for May 2025.</p>'),jsonb_build_object('html','<p>There were 03 reportable environmental incidents this month.</p>'),jsonb_build_object('html','<ul><li>Environmental monitoring programme ongoing.</li><li>Completed monitoring programme with third parties.</li><li>Continued work for the 3, 6 monthly and yearly reports to the regulators.</li></ul>') from public.reporting_periods where period_date='2025-05-01'
on conflict(reporting_period_id) do update set environmental_incident_count=excluded.environmental_incident_count,operations_support=excluded.operations_support,incidents_breakdown=excluded.incidents_breakdown,environmental_incidents=excluded.environmental_incidents,monitoring_program=excluded.monitoring_program,updated_at=now();
